import React, { useState, useEffect } from 'react';
import { Table, Button, Card, Modal, Form, Alert } from 'react-bootstrap';
import { useAuth } from '../context/AuthContext';
import { useForm } from '../hooks/useForm';
import { mockApi } from '../services/api';
import { toast } from 'react-toastify';

export const Users = () => {
  const { user: currentUser } = useAuth();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [error, setError] = useState('');
  
  const { values, handleChange, reset, setValues } = useForm({
    name: '',
    email: '',
    role: 'user'
  });
  
  useEffect(() => {
    loadUsers();
  }, []);
  
  const loadUsers = async () => {
    try {
      setLoading(true);
      const data = await mockApi.getUsers();
      setUsers(data);
    } catch (error) {
      toast.error('Error al cargar usuarios');
    } finally {
      setLoading(false);
    }
  };
  
  const handleOpenModal = (user = null) => {
    if (user) {
      setEditingUser(user);
      setValues({
        name: user.name,
        email: user.email,
        role: user.role || 'user'
      });
    } else {
      setEditingUser(null);
      reset();
    }
    setShowModal(true);
    setError('');
  };
  
  const handleCloseModal = () => {
    setShowModal(false);
    setEditingUser(null);
    reset();
    setError('');
  };
  
  const handleSaveUser = async (e) => {
    e.preventDefault();
    setError('');
    
    try {
      if (editingUser) {
        // Actualizar usuario
        const updated = await mockApi.updateUser(editingUser.id, values);
        toast.success('Usuario actualizado');
        await loadUsers();
      } else {
        // Crear usuario
        await mockApi.register(values);
        toast.success('Usuario creado');
        await loadUsers();
      }
      handleCloseModal();
    } catch (err) {
      setError(err.message || 'Error al guardar usuario');
      toast.error(err.message || 'Error al guardar usuario');
    }
  };
  
  const handleDeleteUser = async (userId) => {
    if (!window.confirm('¿Estás seguro de eliminar este usuario?')) return;
    
    try {
      await mockApi.deleteUser(userId);
      toast.success('Usuario eliminado');
      await loadUsers();
    } catch (error) {
      toast.error('Error al eliminar usuario');
    }
  };
  
  if (loading) {
    return <div className="text-center mt-5">Cargando usuarios...</div>;
  }
  
  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Gestión de Usuarios</h2>
        <Button variant="primary" onClick={() => handleOpenModal()}>
          + Nuevo Usuario
        </Button>
      </div>
      
      <Card className="shadow-sm">
        <Card.Body>
          <Table responsive striped hover>
            <thead>
              <tr>
                <th>ID</th>
                <th>Nombre</th>
                <th>Email</th>
                <th>Rol</th>
                <th>Acciones</th>
              </tr>
            </thead>
            <tbody>
              {users.length === 0 ? (
                <tr>
                  <td colSpan="5" className="text-center text-muted">
                    No hay usuarios registrados
                  </td>
                </tr>
              ) : (
                users.map((user) => (
                  <tr key={user.id}>
                    <td>{user.id}</td>
                    <td>{user.name}</td>
                    <td>{user.email}</td>
                    <td>
                      <span className={`badge bg-${user.role === 'admin' ? 'warning' : 'info'}`}>
                        {user.role || 'user'}
                      </span>
                    </td>
                    <td>
                      <Button
                        variant="outline-primary"
                        size="sm"
                        className="me-2"
                        onClick={() => handleOpenModal(user)}
                      >
                        ✏️
                      </Button>
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => handleDeleteUser(user.id)}
                        disabled={user.id === currentUser?.id}
                      >
                        🗑️
                      </Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </Table>
        </Card.Body>
      </Card>
      
      {/* Modal para crear/editar usuario */}
      <Modal show={showModal} onHide={handleCloseModal}>
        <Modal.Header closeButton>
          <Modal.Title>
            {editingUser ? 'Editar Usuario' : 'Nuevo Usuario'}
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={handleSaveUser}>
          <Modal.Body>
            {error && <Alert variant="danger">{error}</Alert>}
            
            <Form.Group className="mb-3">
              <Form.Label>Nombre</Form.Label>
              <Form.Control
                type="text"
                name="name"
                value={values.name}
                onChange={handleChange}
                required
              />
            </Form.Group>
            
            <Form.Group className="mb-3">
              <Form.Label>Email</Form.Label>
              <Form.Control
                type="email"
                name="email"
                value={values.email}
                onChange={handleChange}
                required
                disabled={!!editingUser}
              />
            </Form.Group>
            
            <Form.Group className="mb-3">
              <Form.Label>Rol</Form.Label>
              <Form.Select
                name="role"
                value={values.role}
                onChange={handleChange}
              >
                <option value="user">Usuario</option>
                <option value="admin">Administrador</option>
              </Form.Select>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={handleCloseModal}>
              Cancelar
            </Button>
            <Button variant="primary" type="submit">
              {editingUser ? 'Actualizar' : 'Crear'}
            </Button>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  );
};