import React, { useEffect, useState } from 'react';
import { Card, Row, Col } from 'react-bootstrap';
import { useAuth } from '../context/AuthContext';
import { mockApi } from '../services/api';

export const Dashboard = () => {
  const { user } = useAuth();
  const [userCount, setUserCount] = useState(0);
  
  useEffect(() => {
    const fetchUserCount = async () => {
      try {
        const users = await mockApi.getUsers();
        setUserCount(users.length);
      } catch (error) {
        console.error('Error fetching users:', error);
      }
    };
    fetchUserCount();
  }, []);
  
  return (
    <div>
      <h2 className="mb-4">Dashboard</h2>
      <Row>
        <Col md={4} className="mb-3">
          <Card className="text-center shadow-sm">
            <Card.Body>
              <Card.Title>👤 Usuario Actual</Card.Title>
              <Card.Text>
                <strong>{user?.name || 'Sin nombre'}</strong>
                <br />
                <small className="text-muted">{user?.email}</small>
              </Card.Text>
            </Card.Body>
          </Card>
        </Col>
        
        <Col md={4} className="mb-3">
          <Card className="text-center shadow-sm">
            <Card.Body>
              <Card.Title>📊 Total Usuarios</Card.Title>
              <Card.Text>
                <h2>{userCount}</h2>
                <small className="text-muted">Usuarios registrados</small>
              </Card.Text>
            </Card.Body>
          </Card>
        </Col>
        
        <Col md={4} className="mb-3">
          <Card className="text-center shadow-sm">
            <Card.Body>
              <Card.Title>✅ Estado</Card.Title>
              <Card.Text>
                <span className="badge bg-success">Activo</span>
                <br />
                <small className="text-muted">Sesión iniciada</small>
              </Card.Text>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </div>
  );
};